package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.function.Supplier;
import net.officefloor.hq.app.asof.AsOfStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.Permissions;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Settles a claim, fixing its due: its amount at its person's grade's rate in force on its date, rounded by the sheet's policy date to
 *  two decimals (a claim bound by a statement: the figure it was bound to). With no rate the due is not
 *  fixed and stays live. Its late charge on the sheet's today is added, then the sheet's floor applied last, and fixed with it. Refused for the user who opened it or last edited it (four eyes), and for a claim
 *  that is not OPEN, and for a role the permission matrix does not let settle. Settled by a clerk when the due is above the clerk limit in force (its person's grade's on the sheet's today when set, else the sheet's; a due that is n/a is within any limit; a steward settles
 *  anything), it goes to PENDING instead (after the proof threshold: one above it with no proofs is refused), nothing fixed, until a steward approves or rejects it. */
public class SettleClaim {
    /** Settled as of a date ({@code on}; blank: the sheet's today): the frozen due is the claim's due as it stood
     *  at the end of that day, as the sheet shown as of it works it out. Refused for a date after the sheet's today,
     *  and for a claim that did not exist then. */
    public void move(@RequestParam(name = "by", required = false) String by,
            @RequestParam(name = "on", required = false) String on, @Val Claim claim,
            PersonRepository people, RateRepository rates, PeriodRepository periods,
            RoleRepository roles, SettingRepository settings, SheetRepository sheets,
            ClaimRepository claims, AsOfStore store)
            throws ClaimStatusException, PeriodClosedException {
        Supplier<String> asOfDue = null;
        if (on != null && !on.isBlank()) {
            LocalDate date;
            try {
                date = LocalDate.parse(on.trim());
            } catch (DateTimeParseException e) {
                throw new ClaimStatusException("Not a date: " + on);
            }
            if (date.isAfter(sheets.today(claim.getSheetId()))) {
                throw new ClaimStatusException("A claim cannot be settled as of a date after the sheet's today");
            }
            String[] then = store.read(claim.getSheetId(), date, () -> {
                Claim was = claims.find(claim.getSheetId(), claim.getId());
                if (was == null) return null;
                return new String[] { dueOf(was, people.find(was.getSheetId(), was.getPersonId()), rates, settings, sheets) };
            });
            if (then == null) {
                throw new ClaimStatusException("The claim did not exist on " + date);
            }
            asOfDue = () -> then[0];
            claim.setSettledAsOf(date.toString());
        }
        settle(by, claim, true, people, rates, periods, roles, settings, sheets, asOfDue);
        // Settled one at a time: in no batch.
        claim.setSettleBatch(null);
    }

    /** The rules of settling one claim, shared with {@link BulkSettleClaims}: moves the claim (unsaved) or throws. */
    static void settle(String by, Claim claim, PersonRepository people, RateRepository rates,
            PeriodRepository periods, RoleRepository roles, SettingRepository settings, SheetRepository sheets)
            throws ClaimStatusException, PeriodClosedException {
        settle(by, claim, true, people, rates, periods, roles, settings, sheets);
    }

    /** As {@link #settle}, the four-eyes and proof rules judged on the claim itself only when {@code judged}
     *  (a part-settle judges them on the original claim, by {@link #judge}, before the split). */
    static void settle(String by, Claim claim, boolean judged, PersonRepository people, RateRepository rates,
            PeriodRepository periods, RoleRepository roles, SettingRepository settings, SheetRepository sheets)
            throws ClaimStatusException, PeriodClosedException {
        settle(by, claim, judged, people, rates, periods, roles, settings, sheets, null);
    }

    /** As {@link #settle}, the due frozen being {@code asOfDue}'s when given (else the due now). */
    static void settle(String by, Claim claim, boolean judged, PersonRepository people, RateRepository rates,
            PeriodRepository periods, RoleRepository roles, SettingRepository settings, SheetRepository sheets,
            Supplier<String> asOfDue) throws ClaimStatusException, PeriodClosedException {
        if (!Permissions.allows(claim.getSheetId(), by, Permissions.SETTLE, roles, settings)) {
            throw new ClaimStatusException("Your role may not settle a claim");
        }
        periods.requireOpen(claim.getSheetId(), claim.getDueBy());
        if (!ClaimStatus.OPEN.name().equals(claim.getStatus())) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be settled");
        }
        if (claim.isDeferred()) {
            throw new ClaimStatusException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
        }
        ClaimStatus settled = ClaimStatus.OPEN.moveTo(ClaimStatus.SETTLED);
        if (judged) requireFourEyes(by, claim);
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        String due = asOfDue != null ? asOfDue.get() : dueOf(claim, person, rates, settings, sheets);
        if (judged) requireProof(claim, person, due, settings);
        if (due != null && Role.CLERK.equals(roles.roleOf(claim.getSheetId(), by == null ? "" : by))) {
            BigDecimal limit = settings.clerkLimit(claim.getSheetId(),
                    person == null ? null : person.gradeOn(sheets.today(claim.getSheetId()).toString()));
            if (limit != null && new BigDecimal(due).compareTo(limit) > 0) {
                claim.setStatus(ClaimStatus.OPEN.moveTo(ClaimStatus.PENDING).name());
                return;
            }
        }
        claim.setStatus(settled.name());
        claim.setSettledDue(due);
    }

    /** The four-eyes and proof rules of settling, judged on the claim (unchanged) alone. */
    static void judge(String by, Claim claim, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets) throws ClaimStatusException {
        requireFourEyes(by, claim);
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        requireProof(claim, person, dueOf(claim, person, rates, settings, sheets), settings);
    }

    /** Refuses the user who opened the claim or last edited it. */
    static void requireFourEyes(String by, Claim claim) throws ClaimStatusException {
        if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(by == null ? "" : by)) {
            throw new ClaimStatusException("The user who opened a claim cannot settle it");
        }
        if (claim.getEditedBy() != null && claim.getEditedBy().equals(by == null ? "" : by)) {
            throw new ClaimStatusException("The user who last edited a claim cannot settle it");
        }
    }

    /** The due the claim settles at now (null: n/a). */
    static String dueOf(Claim claim, Person person, RateRepository rates, SettingRepository settings,
            SheetRepository sheets) {
        Rate rate = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()),
                LocalDate.parse(claim.getDate()), claim.getId());
        // A claim bound by a statement settles at the figure it was bound to.
        // Its late charge on the sheet's today is frozen in.
        Dues.Late late = settings.late(claim.getSheetId(), sheets.today(claim.getSheetId()));
        return Dues.shown(claim, rate == null ? null : Dues.of(claim.getAmount(), rate.pct(),
                late.rounding(claim.getRoundDate())), settings.floor(claim.getSheetId()).on(claim.getDate()), late);
    }

    /** Refuses settling or approving a claim with no proofs (while the sheet's proof kinds are set: with
     *  none of one of them) whose due (null: n/a, never above) is above
     *  the proof threshold in force on the claim's date: its person's grade's (the grade in force on that
     *  date) when one is set, else the sheet's. */
    static void requireProof(Claim claim, Person person, String due, SettingRepository settings) throws ClaimStatusException {
        if (due == null) return;
        java.util.List<String> kinds = settings.proofKinds(claim.getSheetId());
        if (claim.getProofs() > 0 && kinds.stream().allMatch((kind) -> claim.proofsOf(kind) > 0)) return;
        BigDecimal threshold = settings.proofThreshold(claim.getSheetId(),
                person == null ? null : person.gradeOn(claim.getDate()), claim.getDate());
        if (threshold != null && new BigDecimal(due).compareTo(threshold) > 0) {
            throw new ClaimStatusException("A claim whose due is above the proof threshold needs a proof"
                    + (kinds.isEmpty() ? "" : " of each kind: " + String.join(",", kinds)));
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Approves a PENDING claim: it becomes SETTLED, its due fixed at the figure it shows at that moment
 *  (the figure a statement bound it to, else its live figure, with its late charge on the sheet's
 *  today). Refused unless the user is a steward or the person's approver, and for the user who opened it or last edited it, and for one
 *  with no proofs whose due is above the proof threshold in force on its date. */
public class ApproveClaim {
    public void move(@RequestParam(name = "by", required = false) String by, @Val Claim claim,
            PersonRepository people, RateRepository rates, PeriodRepository periods,
            RoleRepository roles, SettingRepository settings, SheetRepository sheets)
            throws ClaimStatusException, PeriodClosedException {
        periods.requireOpen(claim.getSheetId(), claim.getDueBy());
        String user = by == null ? "" : by;
        if (!ClaimStatus.PENDING.name().equals(claim.getStatus())) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be approved");
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        if (!Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), user)) && !isApprover(person, user)) {
            throw new ClaimStatusException("Only a steward or the person's approver can approve a claim");
        }
        if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
            throw new ClaimStatusException("The user who opened a claim cannot approve it");
        }
        if (claim.getEditedBy() != null && claim.getEditedBy().equals(user)) {
            throw new ClaimStatusException("The user who last edited a claim cannot approve it");
        }
        Rate rate = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()),
                LocalDate.parse(claim.getDate()), claim.getId());
        Dues.Late late = settings.late(claim.getSheetId(), sheets.today(claim.getSheetId()));
        String due = Dues.shown(claim, rate == null ? null : Dues.of(claim.getAmount(), rate.pct(),
                late.rounding(claim.getRoundDate())), settings.floor(claim.getSheetId()).on(claim.getDate()), late);
        SettleClaim.requireProof(claim, person, due, settings);
        claim.setStatus(ClaimStatus.PENDING.moveTo(ClaimStatus.SETTLED).name());
        claim.setSettledDue(due);
    }

    /** Whether the user is the person's approver: they may approve or reject the person's PENDING
     *  claims as a steward may. */
    static boolean isApprover(Person person, String user) {
        return person != null && person.getApprover() != null && !user.isEmpty() && person.getApprover().equals(user);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.Permissions;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.voidreason.VoidReasonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Voids a claim; an opened claim keeps its number (still never reused). Refused for a role the
 *  permission matrix does not let void. A SETTLED claim may be voided only by a steward, within
 *  {@link #SETTLED_DAYS} days of its settlement (its status log's SETTLED date) by the sheet's today:
 *  its frozen figure leaves every total (it is kept on the claim, and reported as reversed). While the
 *  sheet has void reasons, a void needs one of them ({@code reason}), kept on the claim; refused without. */
public class VoidClaim {
    public static final int SETTLED_DAYS = 7;

    public void move(@RequestParam(name = "by", required = false) String by,
            @RequestParam(name = "reason", required = false) String reason, @Val Claim claim,
            PeriodRepository periods, RoleRepository roles, SettingRepository settings,
            ClaimLogRepository log, SheetRepository sheets, VoidReasonRepository reasons)
            throws ClaimStatusException, PeriodClosedException, InvalidClaimException {
        String chosen = reason == null ? "" : reason.trim();
        if (reasons.any(claim.getSheetId())) {
            if (chosen.isEmpty() || !reasons.contains(claim.getSheetId(), chosen)) {
                throw new InvalidClaimException("A void needs a reason from the sheet's void reasons");
            }
            claim.setVoidReason(chosen);
        }
        if (ClaimStatus.SETTLED.name().equals(claim.getStatus())) {
            voidSettled(by, claim, periods, roles, log, sheets);
            return;
        }
        if (!Permissions.allows(claim.getSheetId(), by, Permissions.VOID, roles, settings)) {
            throw new ClaimStatusException("Your role may not void a claim");
        }
        periods.requireOpen(claim.getSheetId(), claim.getDueBy());
        claim.setStatus(ClaimStatus.valueOf(claim.getStatus()).moveTo(ClaimStatus.VOID).name());
    }

    private static void voidSettled(String by, Claim claim, PeriodRepository periods, RoleRepository roles,
            ClaimLogRepository log, SheetRepository sheets) throws ClaimStatusException, PeriodClosedException {
        if (!Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), by == null ? "" : by))) {
            throw new ClaimStatusException("Only a steward can void a SETTLED claim");
        }
        periods.requireOpen(claim.getSheetId(), claim.getDueBy());
        LocalDate settledOn = log.settledOn(claim.getSheetId(), claim.getId());
        if (settledOn == null || sheets.today(claim.getSheetId()).isAfter(settledOn.plusDays(SETTLED_DAYS))) {
            throw new ClaimStatusException("A SETTLED claim can be voided only within " + SETTLED_DAYS
                    + " days of its settlement");
        }
        claim.setStatus(ClaimStatus.VOID.name());
        claim.setReversal(true);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** A steward re-dates an OPEN or PENDING claim ({@code date}, yyyy-MM-dd). Its due-by stays as it was
 *  fixed and a figure a statement bound it to stays bound, so its period (the one its due-by falls in)
 *  and its number stay too. Refused for anyone else, for any other status, for a claim due by a day
 *  in a closed period, and for a date that is not a date or is after its person's retirement. */
public class RedateClaim {
    public void redate(@RequestParam(name = "by", required = false) String by,
            @RequestParam(name = "date", required = false) String date, @Val Claim claim,
            PersonRepository people, RoleRepository roles, PeriodRepository periods, Out<Redating> redating) throws ClaimStatusException, InvalidClaimException, PeriodClosedException {
        redating.set(redate(by, claim, date, people, roles, periods));
    }

    /** Re-dates the claim in place by the rules above (writing nothing): the date it had and the one it has now. */
    static Redating redate(String by, Claim claim, String date, PersonRepository people, RoleRepository roles,
            PeriodRepository periods) throws ClaimStatusException, InvalidClaimException, PeriodClosedException {
        String sheetId = claim.getSheetId();
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, by == null ? "" : by))) {
            throw new ClaimStatusException("Only a steward can re-date a claim");
        }
        if (!ClaimStatus.isOpen(claim.getStatus())) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be re-dated");
        }
        LocalDate to;
        try {
            to = LocalDate.parse(date == null ? "" : date.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidClaimException("Not a date: " + date);
        }
        periods.requireOpen(sheetId, claim.getDueBy());
        Person person = people.find(sheetId, claim.getPersonId());
        if (person != null && person.retiredBefore(to)) {
            throw new InvalidClaimException("A claim cannot be dated after its person's retirement");
        }
        String old = claim.getDate();
        claim.setDate(to.toString());
        return new Redating(old, claim.getDate());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: a split that went through, naming the original with its remaining amount and the
 *  new claim's number, then the new claim's opening. */
public class RecordClaimSplit {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Split split, PersonRepository people, Audit audit) {
        audit.record(RecordClaimStatus.line("CLAIM_SPLIT", by, split.original(), people)
                + " into=" + split.created().getNumber());
        audit.record(RecordClaimStatus.line(ClaimStatus.OPEN.event(), by, split.created(), people));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a status change that went through is recorded. */
public class RecordClaimStatus {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Claim claim, PersonRepository people, Audit audit) {
        audit.record(line(ClaimStatus.valueOf(claim.getStatus()).event(), by, claim, people)
                + (ClaimStatus.SETTLED.name().equals(claim.getStatus()) ? due(claim) : "")
                + (claim.isReversal() ? reversed(claim) : "")
                + (ClaimStatus.VOID.name().equals(claim.getStatus()) && claim.getVoidReason() != null
                        ? " reason=" + claim.getVoidReason() : "")
                + (ClaimStatus.SETTLED.name().equals(claim.getStatus()) && claim.getSettledAsOf() != null
                        ? " on=" + claim.getSettledAsOf() : ""));
    }

    /** A claim line: the event, the sheet, the user, then the claim's person, amount, date and number. */
    static String line(String event, String by, Claim claim, PersonRepository people) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        return event + " sheet=" + claim.getSheetId()
                + " by=" + (by == null ? "" : by)
                + " person=" + (person == null ? "" : person.getName())
                + " amount=" + claim.getAmount() + " date=" + claim.getDate()
                + claim.getAuditNumber();
    }

    /** The reversed suffix of a voided SETTLED claim: the frozen figure that left the totals. */
    static String reversed(Claim claim) {
        return " reversed=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue());
    }

    /** The fixed due suffix of a settled claim. */
    static String due(Claim claim) {
        return " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step of an approval: CLAIM_APPROVED with the due it was fixed at. */
public class RecordClaimApproved {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Claim claim, PersonRepository people, Audit audit) {
        audit.record(RecordClaimStatus.line("CLAIM_APPROVED", by, claim, people) + RecordClaimStatus.due(claim));
    }
}

