test("number on settle scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await ui.setSetting(pg_uma, "terms-A", "20");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  await ui.setSetting(pg_uma, "perm-open", "clerk");
  await ui.setSetting(pg_uma, "grace-days", "0");
  await ui.setSetting(pg_uma, "note-threshold", "1.00");
  await ui.setSetting(pg_uma, "grace-A", "5");
  await ui.setSetting(pg_uma, "proof-threshold-C", "0.50");
  await ui.setSetting(pg_uma, "pot", "33.33");
  await ui.setSetting(pg_uma, "review-sla", "5");
  await ui.setSetting(pg_uma, "proof-kinds", "receipt,photo");
  await ui.setSetting(pg_uma, "default-grade", "B");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "tags": "a"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "terms": "20", "contact": " Ada@x "}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "60.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "40.00"})).toBe(true);
  expect(await ui.addPool(pg_uma, "P2")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P2", {"member": "Cam", "share": "100.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "pool:P2", "share": "10.00"})).toBe(true);
  const pl_ben_1 = ui.must(await ui.addPlan(pg_uma, p_ben, {"amount": "99.95", "start": "2026-02-20", "end": "2026-04-30", "every": "10"}));
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "99.95", "date": "2026-02-10", "note": "n"}));
  expect(await ui.claimEditOpen(pg_uma, c_ben_0)).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimEditOpen(pg_vic, c_ben_0)).toBe(false);
  await ui.refresh(pg_uma);
  await ui.claimEditCancel(pg_uma, c_ben_0);
  await ui.refresh(pg_vic);
  expect(await ui.transfer(pg_vic, p_ben, `${sheet}-t`)).toBe(true);
  expect(await ui.periodAction(pg_vic, "2026-04", "close")).toBe(true);
  expect(await ui.inlineGrade(pg_vic, p_cam, "C")).toBe(true);
  expect(await ui.addClaim(pg_vic, p_cam, {"amount": "10.35", "note": "n"})).toBeNull();
  expect(await ui.editPerson(pg_vic, p_cam, {"grade": "A", "gradeFrom": "2026-02-25"}, {"grade": "C"})).toBe(true);
  await ui.refresh(pg_vic);
  expect(await ui.setRate(pg_vic, {"grade": "A", "pct": "12.50", "from": "2026-03-10", "to": "2026-03-25"})).toBe(true);
  expect(await ui.setSettingDated(pg_vic, "clerk-limit", "", "2026-03-05", "")).toBe(true);
  expect(await ui.quickAdd(pg_vic, {"name": "Dot", "amount": "4.00"})).toBeNull();
  await ui.setSetting(pg_vic, "entry-date", "2026-03-01");
  expect(await ui.addClaim(pg_vic, p_cam, {"amount": "25.00", "tags": "a"})).toBeNull();
  expect(await ui.addNote(pg_vic, "hi")).toBe(true);
  expect(await ui.statement(pg_vic, p_cam)).toBe(true);
  await ui.refresh(pg_vic);

